function renderActivity(){const host=document.querySelector('#activityList');if(!host)return;host.replaceChildren();if(!accessToken){const p=document.createElement('p');p.className='empty-activity';p.textContent='Sign in to view workspace activity.';host.append(p);return}let list=[];try{list=JSON.parse(localStorage.getItem(ACTIVITY_KEY))||[]}catch{}if(!list.length){const p=document.createElement('p');p.className='empty-activity';p.textContent='Your project activity will appear here.';host.append(p);return}for(const entry of list.slice(0,8)){const row=document.createElement('div');row.className='activity-row';const icon=document.createElement('span');icon.className='activity-icon green-bg';icon.textContent='✓';const content=document.createElement('div');const title=document.createElement('b');title.textContent=entry.title;const detail=document.createElement('small');detail.textContent=entry.detail;content.append(title,detail);const time=document.createElement('time');time.textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(entry.at));row.append(icon,content,time);host.append(row)}}

function updateSpecPreview(){const idea=document.querySelector('#projectIdea').value.trim(),resource=resourceForIdea(idea),language=String(stackSelect.value||'').split(' · ')[0];let plan='';if(['Python','JavaScript'].includes(language))plan=`BackendDev will prepare a ${resource} collection with list, detail, create, update, and delete routes, plus /health. Data is temporary in-memory storage.`;else if(['Go','C++','Assembly'].includes(language))plan=`This ${language} starter provides a small HTTP /health endpoint. It does not create ${resource} CRUD routes yet; ask AI to add them or edit the code. Data persistence is not included.`;else plan=`This ${language||'language'} starter is a console program, not an HTTP API yet. Add a web framework and routes before testing it as a backend.`;document.querySelector('#specPreview').textContent=idea?plan:'Tell us what you want to build to see what this language starter will create.'}
