function loadProjects() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORE_KEY));
    return Array.isArray(saved) ? [...seeds, ...saved.filter(p => !seeds.some(s => s.id === p.id))] : [...seeds];
  } catch { return [...seeds]; }
}
