function iconFor(language) { return ({TypeScript:'TS',Python:'Py',Go:'Go',Rust:'Rs',Java:'Jv','C#':'C#',Ruby:'Rb',PHP:'PHP','C++':'C++',Assembly:'ASM',Other:'···'})[language] || 'JS'; }
