function setAuthMode(){
  document.querySelector('#smtpSetupHelp').hidden=!recoveryRequestMode;
  const updating=passwordUpdateMode,recovering=recoveryRequestMode,signup=signupMode&&!recovering&&!updating;
  document.querySelector('#authTitle').textContent=updating?'Choose a new password':recovering?'Reset your password':signup?'Create your account':'Welcome back.';
  document.querySelector('#authDescription').textContent=updating?'Set a new password for your BackendDev account.':recovering?'We will email you a secure link if this account exists.':signup?'Create an account to keep your backend projects private and saved.':'Sign in to continue building and managing your projects.';
  document.querySelector('#authSubmit').innerHTML=updating?'Update password <span>→</span>':recovering?'Send reset link <span>→</span>':signup?'Create account <span>→</span>':'Sign in <span>→</span>';
  document.querySelector('#toggleAuth').textContent=signup?'I already have an account':'Create account';
  document.querySelector('#toggleAuth').hidden=recovering||updating;
  document.querySelector('#forgotPassword').hidden=signup||recovering||updating;
  const passwordVisible=!recovering;
  document.querySelector('#passwordLabel').hidden=!passwordVisible;document.querySelector('#authPasswordWrap').hidden=!passwordVisible;document.querySelector('#authPassword').required=passwordVisible;resetPasswordVisibility('authPassword');
  document.querySelector('#passwordStrength').hidden=!(signup||updating);
  document.querySelector('#passwordPolicyNote').hidden=signup||updating||recovering;
  document.querySelector('#authPassword').minLength=signup||updating?12:8;
  document.querySelector('#authPassword').placeholder='Enter your password';
  document.querySelector('#authPassword').autocomplete=signup||updating?'new-password':'current-password';
  const confirmVisible=signup||updating;document.querySelector('#authConfirmWrap').hidden=!confirmVisible;document.querySelector('#confirmLabel').hidden=!confirmVisible;resetPasswordVisibility('authConfirm');document.querySelector('#authConfirm').required=confirmVisible;document.querySelector('#authConfirm').minLength=confirmVisible?12:8;
  document.querySelector('#termsAcceptLabel').hidden=!signup;document.querySelector('#termsAccept').required=signup;
  document.querySelector('.auth-access-note').hidden=recovering||updating;
  document.querySelector('#resendConfirm').hidden=true;
  document.querySelector('#authFootnote').textContent=signup?'Free to get started · Your projects stay private':recovering?'The reset link expires according to your Supabase Auth settings.':'Private by design · Your projects belong to your account';
  updatePasswordStrength();
}
