document.querySelector('#sendApiRequest').addEventListener('click',async()=>{if(!requireSignIn())return;const out=document.querySelector('#apiOutput'),raw=document.querySelector('#apiUrl').value.trim(),method=document.querySelector('#apiMethod').value,bodyText=document.querySelector('#apiBody').value.trim();let target;try{target=new URL(raw);if(!['http:','https:'].includes(target.protocol))throw Error()}catch{out.textContent='Enter a valid http:// or https:// API URL.';return}let payload;try{if(bodyText)payload=JSON.parse(bodyText)}catch{out.textContent='Request body must be valid JSON.';return}out.textContent='Sending request…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000),started=performance.now();try{const response=await fetch(target,{method,signal:controller.signal,headers:payload?{'content-type':'application/json'}:undefined,body:payload?JSON.stringify(payload):undefined});const text=await response.text();out.textContent=`${response.status} ${response.statusText} · ${Math.round(performance.now()-started)} ms\n\n${text.slice(0,20000)||'(empty response)'}`;recordActivity('API request sent',`${method} ${target.host} · ${response.status}`)}catch(error){const localTarget=['localhost','127.0.0.1','::1'].includes(target.hostname);out.textContent=error.name==='AbortError'?'Request timed out after 15 seconds.':localTarget?`Could not reach ${target.origin}. Start the API on this same device first (Run backend is local-only), use its /health route, and allow browser requests from ${location.origin} in CORS. If BackendDev is open on another device, localhost points to that device instead.`:`The request could not reach ${target.origin}. Check that the API is online, uses HTTPS when needed, and allows browser requests from ${location.origin} in CORS. Browser security hides the exact network/CORS cause.`;recordActivity('API request failed',`${method} ${target.host}`)}finally{clearTimeout(timer)}});
function readinessReport(project){const files=Object.entries(project.files||{}).filter(([name])=>!name.startsWith('migration-backup/')),paths=files.map(([name])=>name.toLowerCase()),source=files.filter(([name])=>/\.(py|js|mjs|ts|go|rs|java|cpp|h|asm|sql)$/i.test(name)).map(([name,text])=>[name,String(text)]),all=source.map(([,text])=>text).join('\n'),checks=[];const add=(label,ok,detail)=>checks.push(`${ok?'PASS':'TODO'} · ${label}${detail?` — ${detail}`:''}`);add('Automated tests',paths.some(name=>/(^|\/)(test|tests|spec|specs)(\/|\.|$)|(^|\/)(test_.*\.py|.*\.test\.[jt]s)$/i.test(name)),'');add('OpenAPI contract',paths.includes('openapi.json'),'');add('Persistent data store',/sqlite|postgres|mysql|mongodb|mongoose|prisma|sqlalchemy|psycopg|database_url/i.test(all),'');add('Authentication or authorization',/authenticate|authorization|\bjwt\b|supabase|session|passport/i.test(all),'');add('Environment template',paths.some(name=>/(^|\/)\.env\.(example|sample|template)$/.test(name)),'');add('Deployment container/config',paths.some(name=>/(^|\/)(dockerfile|docker-compose\.ya?ml|render\.ya?ml|fly\.toml|procfile)$/.test(name)),'');const warnings=[];const checksForSecrets=[/\bsb_secret_[a-z0-9_-]{12,}/i,/\bsk-(?:proj-)?[a-z0-9_-]{24,}/i,/\bgh[pousr]_[a-z0-9]{20,}/i,/\bAKIA[0-9A-Z]{16}\b/,/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/];for(const [name,text] of source){const lines=text.split('\n');for(let i=0;i<lines.length;i++){const line=lines[i];if(checksForSecrets.some(pattern=>pattern.test(line))){warnings.push(`Potential credential in ${name}:${i+1}; rotate it if it was real and move it to a secret store.`);break}if(/\beval\s*\(/.test(line)||/child_process\.(?:exec|execSync)\s*\(/.test(line))warnings.push(`Review dynamic code or shell execution in ${name}:${i+1}.`);if(/access-control-allow-origin['"\s:]+\*/i.test(line))warnings.push(`Wildcard CORS is enabled in ${name}:${i+1}; restrict origins before production.`)}}const missing=checks.filter(line=>line.startsWith('TODO')).length;return [`PROJECT READINESS · ${project.name}`,`Language: ${project.language} · ${project.framework}`,`Static checks: ${checks.length-missing}/${checks.length} present`,...checks,...(warnings.length?['','REVIEW REQUIRED',...warnings]:['','No high-confidence credential or dynamic-execution patterns were detected.']),`\nThis source scan is heuristic. It cannot verify authorization correctness, dependency vulnerabilities, deployed configuration, or production security.`].join('\n')}
document.querySelector('#readinessReview').addEventListener('click',async()=>{if(!requireSignIn())return;const project=projects.find(item=>item.id===currentProjectId);if(!project)return;try{await saveEditorBeforeAction(project);document.querySelector('#checkOutput').textContent=readinessReport(project);recordActivity(`${project.name} readiness review`,'Static project checklist completed')}catch(error){document.querySelector('#checkOutput').textContent=`Could not review project: ${error.message}`}});document.querySelector('#openApiFile').addEventListener('click',()=>{const project=projects.find(item=>item.id===currentProjectId);if(!project)return;if(!project.files?.['openapi.json']){notify('This starter does not expose HTTP routes to document yet.');return}const select=document.querySelector('#fileSelect');select.value='openapi.json';select.dispatchEvent(new Event('change'));document.querySelector('#fileEditor').scrollIntoView({behavior:'smooth',block:'center'})});document.querySelector('#closeWorkspace').addEventListener('click',()=>document.querySelector('#workspaceDialog').close());
document.querySelector('#downloadProject').addEventListener('click',async()=>{if(!requireSignIn())return;const p=projects.find(x=>x.id===currentProjectId);if(!p)return;const button=document.querySelector('#downloadProject');button.disabled=true;try{await saveEditorBeforeAction(p);const blob=zipProjectFiles(p.files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'backenddev'}-project.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);recordActivity(`${p.name} exported`,'Source files downloaded as a ZIP archive; secret files excluded');notify('Project ZIP downloaded. Secret files such as .env and private keys were excluded.')}catch(error){notify(`Could not export project: ${error.message}`)}finally{button.disabled=false}});
