feedbackForm.addEventListener('submit',async event=>{event.preventDefault();if(!requireSignIn())return;const button=document.querySelector('#sendFeedback'),status=document.querySelector('#feedbackStatus');button.disabled=true;status.textContent='Sending your feedback…';try{await api('/api/feedback',{method:'POST',body:JSON.stringify({category:document.querySelector('#feedbackCategory').value,subject:document.querySelector('#feedbackSubject').value,message:document.querySelector('#feedbackMessage').value})});feedbackForm.reset();feedbackDialog.close();notify('Feedback sent to the BackendDev owner. Thank you.')}catch(error){status.textContent=error.message}finally{button.disabled=false}});
const adminDialog=document.querySelector('#adminDialog');
document.querySelector('#adminButton').addEventListener('click',async()=>{if(!requireSignIn())return;try{const access=await api('/api/admin/me');if(!access.isAdmin)throw Error('This signed-in account is not listed as an owner. Check APP_ADMIN_EMAILS in Render.');if(access.mfaCheckAvailable===false){adminDialog.showModal();document.querySelector('#adminStatus').textContent='Your owner account is recognized. Supabase could not check authenticator status. Refresh security settings or check Supabase Auth MFA configuration.';return}if(!access.mfaEnrolled||!access.mfaVerified){if(access.mfaEnrolled&&!access.mfaVerified){notify('Your authenticator is already set up. Sign out, sign in again, and enter its code to unlock owner controls.');return}securityDialog.showModal();await loadSecuritySettings();return}adminDialog.showModal();document.querySelector('#adminStatus').textContent='Checking owner access and setup…';await loadAdminOverview();if(access.controlsReady)await Promise.all([loadAdminUsers(),loadAdminProjects(),loadAdminFeedback()])}catch(error){notify(error.message)}});
document.querySelector('#closeAdmin').addEventListener('click',()=>adminDialog.close());
 async function loadAdminOverview(){const status=document.querySelector('#adminStatus'),fields={auth:'#adminAuthHealth',admin:'#adminKeyHealth',ai:'#adminAiHealth',runner:'#adminRunnerHealth'};for(const selector of Object.values(fields))document.querySelector(selector).textContent='Checking…';try{const data=await api('/api/admin/setup-status'),checks=Object.fromEntries(data.checks.map(check=>[check.key,check]));document.querySelector(fields.auth).textContent=checks.supabase?.ok&&checks.projects?.ok?'Ready':checks.supabase?.message||checks.projects?.message||'Needs configuration';document.querySelector(fields.admin).textContent=checks.adminApi?.ok?'Ready':checks.adminKey?.message||checks.adminApi?.message||'Unavailable';document.querySelector(fields.ai).textContent=checks.ai?.ok?'Configured':'Needs model settings';document.querySelector(fields.runner).textContent=checks.runner?.message||'Unavailable';const problems=data.checks.filter(check=>!check.ok).map(check=>check.message);document.querySelector('#adminRuntimeNote').textContent=problems.length?problems.join(' '):'Required services are responding. Provider-specific AI delivery is confirmed when you generate a proposal. Secrets are never displayed.';status.textContent=checks.adminApi?.ok?'Owner identity verified. Setup checks are current.':'Owner identity verified. Follow the service status guidance above before using owner management.'}catch(error){for(const selector of Object.values(fields))document.querySelector(selector).textContent='Unavailable';document.querySelector('#adminRuntimeNote').textContent='Could not check service settings. '+error.message;status.textContent=error.message}}
document.querySelector('#refreshAdminOverview').addEventListener('click',loadAdminOverview);
async function loadAdminUsers(){
  const host=document.querySelector('#adminUsers'),status=document.querySelector('#adminStatus');host.textContent='Loading accounts…';
  try{
    const data=await api('/api/admin/users');document.querySelector('#adminUserCount').textContent=String(data.users.length);host.replaceChildren();
    if(!data.users.length){host.textContent='No accounts found.';return}
    for(const user of data.users){
      const row=document.createElement('article');row.className='admin-row';const info=document.createElement('span'),email=document.createElement('b'),meta=document.createElement('small'),actions=document.createElement('div');actions.className='admin-actions';
      email.textContent=user.email||'No email';meta.textContent='Created '+(user.createdAt?new Date(user.createdAt).toLocaleDateString():'unknown')+' · '+(user.confirmedAt?'Email confirmed':'Email unconfirmed')+(user.lastSignInAt?' · Last sign-in '+new Date(user.lastSignInAt).toLocaleDateString():'');info.append(email,meta);
      const suspended=Boolean(user.bannedUntil&&new Date(user.bannedUntil)>new Date()),toggle=document.createElement('button');toggle.type='button';toggle.className='outline';toggle.textContent=suspended?'Restore access':'Suspend';
      toggle.addEventListener('click',async()=>{toggle.disabled=true;try{await api('/api/admin/users/'+encodeURIComponent(user.id)+'/'+(suspended?'restore':'suspend'),{method:'POST',body:'{}'});status.textContent=(user.email||'Account')+' '+(suspended?'restored':'suspended')+'.';await loadAdminUsers()}catch(error){status.textContent=error.message;toggle.disabled=false}});
      const remove=document.createElement('button');remove.type='button';remove.className='outline danger-action';remove.textContent='Delete account';
      remove.addEventListener('click',async()=>{if(!confirm('Permanently delete '+(user.email||'this account')+' and its owned project rows? This cannot be undone.'))return;remove.disabled=true;try{await api('/api/admin/users/'+encodeURIComponent(user.id),{method:'DELETE'});status.textContent=(user.email||'Account')+' deleted.';await Promise.all([loadAdminUsers(),loadAdminProjects()])}catch(error){status.textContent=error.message;remove.disabled=false}});
      actions.append(toggle,remove);row.append(info,actions);host.append(row);
    }
  }catch(error){host.textContent='Could not load accounts.';status.textContent=error.message}
}
async function viewAdminProject(projectId){
  const dialog=document.querySelector('#adminProjectDialog'),title=document.querySelector('#adminProjectTitle'),meta=document.querySelector('#adminProjectMeta'),select=document.querySelector('#adminProjectFile'),content=document.querySelector('#adminProjectContent');
  title.textContent='Loading project…';meta.textContent='Fetching private project details';select.replaceChildren();content.textContent='';dialog.showModal();
  try{const result=await api('/api/admin/projects/'+encodeURIComponent(projectId)),project=result.project;title.textContent=project.name;meta.textContent=project.language+' · '+project.framework+' · owner '+project.owner_id+' · '+project.status;const files=Object.entries(project.files||{});if(!files.length){select.disabled=true;content.textContent='This project has no saved files.';return}select.disabled=false;select.replaceChildren(...files.map(([file])=>{const option=document.createElement('option');option.value=file;option.textContent=file;return option}));const showFile=()=>{content.textContent=String(project.files[select.value]??'')};select.onchange=showFile;showFile()}catch(error){meta.textContent=error.message;content.textContent='Could not load project files.'}
}
document.querySelector('#closeAdminProject').addEventListener('click',()=>document.querySelector('#adminProjectDialog').close());
async function loadAdminProjects(){
  const host=document.querySelector('#adminProjects'),status=document.querySelector('#adminStatus');host.textContent='Loading project records…';
  try{
    const data=await api('/api/admin/projects');document.querySelector('#adminProjectCount').textContent=String(data.projects.length);host.replaceChildren();
    if(!data.projects.length){host.textContent='No projects found.';return}
    for(const project of data.projects){
      const row=document.createElement('article');row.className='admin-row';const info=document.createElement('span'),name=document.createElement('b'),meta=document.createElement('small'),actions=document.createElement('div');actions.className='admin-actions';
      name.textContent=project.name;meta.textContent=project.language+' · '+project.framework+' · owner '+project.owner_id;info.append(name,meta);
      const view=document.createElement('button');view.type='button';view.className='outline';view.textContent='View files';view.addEventListener('click',()=>viewAdminProject(project.id));
      const remove=document.createElement('button');remove.type='button';remove.className='outline danger-action';remove.textContent='Delete project';remove.addEventListener('click',async()=>{if(!confirm('Permanently delete project “'+project.name+'”? This cannot be undone.'))return;remove.disabled=true;try{await api('/api/admin/projects/'+encodeURIComponent(project.id),{method:'DELETE'});status.textContent=project.name+' deleted.';await loadAdminProjects()}catch(error){status.textContent=error.message;remove.disabled=false}});
      actions.append(view,remove);row.append(info,actions);host.append(row);
    }
  }catch(error){host.textContent='Could not load projects.';status.textContent=error.message}
}
async function loadAdminFeedback(){
  const host=document.querySelector('#adminFeedback'),status=document.querySelector('#adminStatus');host.textContent='Loading feedback…';
  try{
    const data=await api('/api/admin/feedback');document.querySelector('#adminOpenFeedbackCount').textContent=String(data.feedback.filter(item=>item.status!=='Resolved').length);host.replaceChildren();
    if(!data.feedback.length){host.textContent='No user feedback yet.';return}
    for(const item of data.feedback){
      const row=document.createElement('article');row.className='admin-row feedback-row';const info=document.createElement('div'),title=document.createElement('b'),meta=document.createElement('small'),message=document.createElement('p'),actions=document.createElement('div'),select=document.createElement('select');info.className='feedback-info';
      title.textContent=item.subject;meta.textContent=item.category+' · '+item.user_email+' · '+(item.created_at?new Date(item.created_at).toLocaleString():'date unknown');message.textContent=item.message;info.append(title,meta,message);actions.className='feedback-actions';
      if(item.user_email){const reply=document.createElement('a');reply.className='outline';reply.href='mailto:'+encodeURIComponent(item.user_email)+'?subject='+encodeURIComponent('BackendDev feedback: '+item.subject);reply.textContent='Reply by email';actions.append(reply)}
      for(const optionText of ['New','In review','Resolved']){const option=document.createElement('option');option.value=optionText;option.textContent=optionText;select.append(option)}select.value=item.status;select.setAttribute('aria-label','Set status for '+item.subject);select.addEventListener('change',async()=>{const chosen=select.value;select.disabled=true;try{await api('/api/admin/feedback/'+encodeURIComponent(item.id),{method:'PUT',body:JSON.stringify({status:chosen})});item.status=chosen;document.querySelector('#adminOpenFeedbackCount').textContent=String([...host.querySelectorAll('.feedback-row')].filter(node=>node.querySelector('select')?.value!=='Resolved').length);status.textContent='Feedback marked '+chosen.toLowerCase()+'.'}catch(error){status.textContent=error.message;select.value=item.status}finally{select.disabled=false}});
      actions.append(select);row.append(info,actions);host.append(row);
    }
  }catch(error){host.textContent='Could not load user feedback.';status.textContent=error.message}
}
document.querySelector('#loadAdminUsers').addEventListener('click',loadAdminUsers);document.querySelector('#loadAdminProjects').addEventListener('click',loadAdminProjects);document.querySelector('#loadAdminFeedback').addEventListener('click',loadAdminFeedback);
